var e={drugs:{propranolol:!0,carvedilol:!1}},t={drugs:{propranolol:!1,carvedilol:!0}},o={label:"Response to the drug",param:"nsbbGain",min:0,max:2,step:.1,ends:["Non-responder","Strong responder"]},s={id:"treatment",level:"advanced",title:"Lowering portal pressure",minutes:10,sections:[["The patient",["Lowering portal pressure"]],["Beta-blockers",["Nonselective beta-blocker"]],["Bleeding and HRS-AKI",["Acute variceal bleeding","Hepatorenal syndrome"]],["Compared",["Compared"]],["Before the sinusoids",["Schistosomiasis"]]],summary:"Propranolol, carvedilol, octreotide, terlipressin and TIPS in one patient with decompensated cirrhosis, the HVPG fall with each, and a patient with schistosomiasis whose resistance is presinusoidal, where carvedilol adds little.",objectives:["Explain how each drug lowers portal pressure: inflow, resistance or both","Explain why carvedilol lowers the HVPG more than propranolol only where the resistance is sinusoidal","Explain how a vasoactive drug lowers portal pressure in acute variceal bleeding","Judge a drug by the fall in the HVPG, and know when the HVPG misleads"],checks:[["Why does carvedilol lower the HVPG more than propranolol?","It also blocks \u03B11 receptors, so it lowers intrahepatic resistance as well as portal inflow."],["On propranolol the heart rate falls from 80 to 58 bpm, but the HVPG only from 18 to 17.5 mmHg. Has the portal pressure responded?","No. The heart rate shows the \u03B21 blockade, not the portal response; a fall <10% marks a non-responder."],["Why does the \u03B11 effect of carvedilol add little in schistosomiasis?","The resistance is periportal fibrosis of the portal venules, upstream of the sinusoids where its \u03B11 effect acts."],["On carvedilol the HVPG falls a little in schistosomiasis. Did the portal pressure fall more?","No. The HVPG reflects sinusoidal pressure, not portal venous pressure; the portal pressure fell about as much as on propranolol."]],slides:[{id:"target",preset:"cirr-decomp",cam:"route",labels:["CONF","SIN_R","RHV","RA"],tool:{kind:"profile"},data:"tiles",key:["hvpg"],tiles:["varix"],kicker:"Lowering portal pressure",site:"sin",title:"A patient with decompensated cirrhosis",vignette:"A 58-year-old woman with MASH cirrhosis has ascites controlled on spironolactone and furosemide. A surveillance EGD shows large esophageal varices. She has never bled.",line:"In this case the HVPG is {hvpg}, with large varices and ascites. Treatment lowers portal inflow or intrahepatic resistance, or bypasses the liver.",notes:"Portal pressure = flow \xD7 resistance. Nonselective beta-blockers (NSBBs) and the vasoactive drugs used in variceal bleeding reduce portal inflow; carvedilol also lowers intrahepatic resistance; TIPS bypasses it. Endoscopic variceal ligation (EVL) treats the varix, not the pressure. Treating the cause (alcohol abstinence, antiviral therapy) lowers the resistance over months to years. On an NSBB, an HVPG fall of \u226510%, or to \u226412 mmHg, counts as a response (Baveno VIII Table 3).",ask:["Name a treatment that reduces portal inflow and one that lowers intrahepatic resistance.","Inflow: propranolol, octreotide, terlipressin. Resistance: carvedilol, treating the cause; TIPS bypasses it."]},{id:"prop",lens:"flow",params:e,cam:[380,110,930,710],labels:["SMV","CONF"],tool:{kind:"hvpg"},data:"tiles",key:["hvpgFall"],tiles:[],delta:"target",hvpgResp:"target",whatIf:o,kicker:"Nonselective beta-blocker",site:"sin",title:"Propranolol lowers portal inflow",line:"At a starting dose, \u03B21 blockade lowers cardiac output and \u03B22 blockade leaves splanchnic \u03B1-adrenergic vasoconstriction unopposed. Portal inflow falls to {pvFlow}, the HVPG to {hvpg}.",notes:"Propranolol (or nadolol) is titrated to a resting heart rate of 55 to 60 bpm, keeping systolic blood pressure >90 mmHg. It prevents a first variceal bleed from large varices and, with EVL, rebleeding. About a third to a half of patients achieve a protective HVPG fall. In refractory ascites with hypotension or acute kidney injury (AKI), the dose is reduced or stopped. The model shows a starting dose: the heart rate falls to about 73 bpm, and titration would take it to 55 to 60 bpm. Colored by flow, the mesenteric and portal veins thin. The tile shows the percent fall from the untreated patient: \u226510% marks a response.",ask:["How is propranolol titrated?","To a resting heart rate of 55 to 60 bpm, keeping systolic blood pressure >90 mmHg."]},{id:"carv",question:"Which lever does carvedilol pull?",lens:"since",since:"prop",sinceLabel:"propranolol",params:{drugs:{propranolol:!1,carvedilol:!0}},cam:"liver",glow:["liver"],tool:{kind:"hvpg"},data:"tiles",key:["hvpgFall"],tiles:[],delta:"target",hvpgResp:"target",whatIf:o,cite:"Baveno VIII 3.15; PREDESCI (Villanueva, Lancet 2019)",kicker:"Nonselective beta-blocker",site:"sin",title:"Carvedilol also lowers intrahepatic resistance",line:"Its \u03B11 blockade is thought to lower sinusoidal tone: the HVPG falls further, to {hvpg}, the blood pressure to {map}. Reduce the dose if systolic BP stays <90 mmHg.",notes:"Carvedilol 6.25 to 12.5 mg/day. Its \u03B11 blockade relaxes activated, contractile hepatic stellate cells and lowers intrahepatic resistance, so it lowers the HVPG more than propranolol and achieves a protective fall in about half of propranolol nonresponders. Baveno VIII recommends a nonselective beta-blocker, preferably carvedilol, in compensated cirrhosis with clinically significant portal hypertension, to prevent decompensation. In PREDESCI, 201 patients with compensated cirrhosis and CSPH took a beta-blocker (propranolol, or carvedilol by their response to propranolol) or placebo; decompensation or death occurred in 16% versus 27% (hazard ratio 0.51), driven mostly by less ascites. Monitor blood pressure, especially with ascites. Both levers move: portal inflow falls as with propranolol, and intrahepatic resistance falls as well.",ask:["Why does carvedilol lower HVPG more than propranolol?","Its \u03B11 blockade also lowers intrahepatic vascular resistance."]},{id:"carv-sin",lens:"flow",cam:"lobule:sinusoid",terms:{sinusoids:"lobule:sinusoid"},tool:{kind:"hvpg"},data:"tiles",key:["hvpgFall"],tiles:[],delta:"target",hvpgResp:"target",compare:[{label:"Propranolol",params:e},{label:"Carvedilol",own:!0,params:t}],kicker:"Nonselective beta-blocker",site:"sin",title:"Carvedilol lowers the HVPG more than propranolol in cirrhosis",line:"In cirrhosis most of the resistance lies in the sinusoids. The \u03B11 blockade of carvedilol is thought to relax hepatic stellate cells, so the HVPG falls to {hvpg}.",notes:"Switch between the two drugs: carvedilol acts on both flow and resistance, so it lowers the HVPG more; in trials, by about 2 mmHg more than propranolol. In the model the difference between the two widens as the sinusoidal resistance grows, from under 1 mmHg in mild cirrhosis to about 2 mmHg in advanced disease. Baveno VIII prefers carvedilol in compensated cirrhosis with clinically significant portal hypertension, to prevent decompensation, and it remains a choice with ascites and varices. Whenever systolic BP stays <90 mmHg, MAP <65 mmHg, or AKI develops, reduce the dose or stop the drug, and restart it once these resolve (Baveno VIII 3.15, 4.6).",ask:["Why does carvedilol lower the HVPG more than propranolol in cirrhosis?","Unlike propranolol, it lowers sinusoidal resistance, which is most of the resistance in cirrhosis."]},{id:"oct",lens:"flow",params:{drugs:{carvedilol:!1,octreotide:!0}},cam:"portal",labels:["SMV","CONF"],tool:{kind:"profile"},data:"tiles",key:["pv"],tiles:["pvFlow"],delta:"target",kicker:"Acute variceal bleeding",site:"sin",title:"Octreotide reduces splanchnic inflow",line:"Octreotide, a somatostatin analog, inhibits the release of splanchnic vasodilatory peptides, so splanchnic inflow falls to {pvFlow}. Its effect on portal pressure is modest and partly transient.",notes:"Suspected variceal bleeding: octreotide at once (a 50 \xB5g bolus, then 25 to 50 \xB5g/h), continued for 2 to 5 days. The full management sequence is in the Acute variceal bleeding talk. Octreotide is the vasoactive drug used for bleeding in the US; elsewhere terlipressin or somatostatin are alternatives. Its effect on portal pressure is modest and partly transient, so the model gives it a smaller fall than terlipressin (splanchnic resistance \xD7 1.35 against \xD7 1.9), in line with HVPG studies of somatostatin analogs (Escorsell 2001, Baik 2005). Colored by flow, the portal vein thins.",ask:["How does octreotide lower the portal pressure, and why is the effect modest?","It reduces splanchnic inflow; the effect is modest and partly transient."]},{id:"terli",lens:"flow",params:{drugs:{octreotide:!1,terlipressin:!0}},cam:"portal",labels:["SMV","CONF"],tool:{kind:"profile"},data:"tiles",key:["map"],tiles:["map","rpp","pvFlow"],delta:"target",compare:[{label:"Octreotide",params:{drugs:{octreotide:!0,terlipressin:!1}}},{label:"Terlipressin",own:!0,params:{drugs:{octreotide:!1,terlipressin:!0}}}],kicker:"Terlipressin",site:"sin",title:"Terlipressin in variceal bleeding and HRS-AKI",line:"This vasopressin analog constricts the dilated splanchnic arterioles. Portal inflow falls to {pvFlow}, which helps in variceal bleeding; with albumin, renal perfusion pressure (RPP) rises to {rpp} in HRS-AKI.",notes:"Outside the US, terlipressin is a first-line vasoactive drug for acute variceal bleeding (2 mg IV every 4 to 6 hours for the first 24 to 48 hours, then 1 mg every 4 to 6 hours, AASLD 2024), and it lowers the portal pressure more than octreotide. In the US it is approved for hepatorenal syndrome with acute kidney injury (HRS-AKI), not for variceal bleeding. It is given with albumin: Baveno VIII advises terlipressin and albumin for HRS-AKI (6.18), and terlipressin preferably as a continuous infusion, starting at 2 to 3 mg in 24 hours, because it causes fewer adverse events than boluses (6.19). It is avoided with hypoxia or volume overload, because of the risk of respiratory failure; ischemia is another risk, and serum sodium is monitored for hyponatremia (Baveno VIII 5.9). Norepinephrine is the alternative where terlipressin is unavailable or not tolerated (6.20). The model has no kidneys: the RPP tile is the MAP minus the intra-abdominal pressure (RPP = MAP \u2212 IAP), which drives renal perfusion, not renal function. Colored by flow, the mesenteric and portal veins thin further.",ask:["What is given with terlipressin for HRS-AKI?","Albumin."]},{id:"vs",params:{tips:{on:!0},drugs:{propranolol:!1,carvedilol:!1,octreotide:!1,terlipressin:!1}},cam:"liver",tool:{kind:"profile"},data:"tiles",key:["ppg"],tiles:["liver"],delta:"target",kicker:"Compared",site:"sin",title:"TIPS versus drug therapy",line:"Drugs lower the gradient by a few mmHg. A TIPS lowers the portal pressure gradient (PPG) to {ppg}, but diverts portal blood away from the liver.",notes:"The same patient with a TIPS; each drug alone is taught on the slides before. In the model propranolol lowers the HVPG by about 13% and carvedilol by about 19%, close to what they do in patients; TIPS brings the PPG to <12 mmHg but halves sinusoidal perfusion. The TIPS talks cover the stent, its flow and its cost.",ask:["Why does TIPS lower the gradient so much more than any drug?","The drugs reduce portal inflow or vascular tone; TIPS creates a low-resistance channel that bypasses the sinusoids."]},{id:"flowres",cam:"liver",visual:"plane",plane:{base:"flow-ppg",x:{key:"pvFlow",min:0,max:1.6,ticks:[0,.4,.8,1.2,1.6],name:"Portal flow, L/min",short:"Flow, L/min",abbr:"Flow"},iso:{rays:[5,10,20,30,40]}},of:[{id:"target",name:"No treatment",short:"Before"},{id:"prop",from:"target",name:"Propranolol",short:"Prop."},{id:"carv",from:"target",name:"Carvedilol",short:"Carv."},{id:"oct",from:"target",name:"Octreotide",short:"Oct."},{id:"terli",from:"target",name:"Terlipressin",short:"Terli."},{id:"vs",from:"target",name:"TIPS"}],kicker:"Compared",title:"Each treatment moves the patient along flow or resistance",line:"Each ring is the patient before treatment, each dot on treatment. Drugs that reduce inflow move the dot left; a TIPS drops it to a lower resistance line.",notes:"Portal pressure = flow \xD7 resistance (Ohm's law), so a patient is a point on a plane: portal flow across, the PPG up, and every line from the origin is one resistance (the PPG divided by the flow, in mmHg per L/min). Propranolol, octreotide and terlipressin reduce inflow, so the dot moves left; the pressure falls less than the flow, so it ends on a steeper line. Carvedilol also relaxes the sinusoids, so its dot moves left and stays close to the line it started on. The TIPS creates a portosystemic channel: the flow rises and the pressure falls, so the dot lands on a much lower line. The resistance on this plane is that of the whole portal circuit (PPG \xF7 flow), not intrahepatic resistance alone. The numbers are the model's for this one patient, not trial results.",ask:["Which treatments move the patient left on this plane, and which drop them to a lower line?","The drugs that reduce inflow move it left. A TIPS lowers the resistance, so the dot drops to a lower line; carvedilol stays near its line because it lowers resistance as well as flow."]},{id:"schisto",preset:"schisto",params:t,caseQ:"Will carvedilol add much to propranolol here?",cam:"lobule:triad",callout:{at:"triad",label:"Resistance"},terms:{"portal venules":"lobule:triad"},data:"tiles",tiles:["pv","hvpg"],key:["pv"],compare:[{label:"Propranolol",params:e},{label:"Carvedilol",own:!0,params:t}],vignette:"A 38-year-old woman from the Senegal River region has a large spleen and large esophageal varices on EGD. Her liver tests are normal, and she has never bled.",kicker:"Schistosomiasis",site:"presin",title:"Carvedilol adds little when the resistance is before the sinusoids",line:"The resistance lies in fibrosed portal venules. The \u03B11 effect of carvedilol acts on the sinusoids downstream, so portal pressure falls only as far as on propranolol, to {pv}.",notes:"Schistosome eggs lodge in the small portal venules, and the granulomas heal as periportal fibrosis. The sinusoids are spared, so the wedged hepatic venous pressure (WHVP) reflects near-normal sinusoidal pressure and the HVPG underestimates portal pressure. Porto-sinusoidal vascular disorder (PSVD) gives the same presinusoidal picture without the parasite. Switch between the two drugs: the portal venous pressure barely changes, because the \u03B11 effect of carvedilol acts downstream of the resistance. The HVPG does fall a little more on carvedilol, as sinusoidal tone falls, but in presinusoidal disease the HVPG never reflected portal pressure, so that fall does not protect the varices. With the resistance fixed in fibrosed portal venules, reducing inflow is the only remaining way to lower portal pressure; most trials in non-cirrhotic portal hypertension used propranolol. For vascular liver disease Baveno VIII finds the evidence insufficient to prefer carvedilol over other beta-blockers (8.9), and no evidence to favor banding over a beta-blocker for primary prophylaxis (8.8). In practice: carvedilol is preferred in cirrhosis with clinically significant portal hypertension (CSPH); in PSVD, an NSBB or EVL, with no beta-blocker preferred; with hypotension or AKI, reduce the dose or stop (Baveno VIII 3.15, 4.6, 8.8, 8.9).",ask:["Switch to propranolol. What happens to the portal vein pressure, and why?","It barely changes: the \u03B11 effect of carvedilol acts on the sinusoids, downstream of the resistance in the portal venules."]},{id:"relation",preset:"cirr-decomp",cam:"liver",glow:["liver"],tool:{kind:"curve",x:"hvpg",param:"cirrhosis",from:.5,to:1,step:.05,lines:["hvpg"],label:"HVPG before the drug",against:[{label:"Carvedilol",params:t,pair:!0,own:"No change"},{label:"Propranolol",params:e,pair:!0}],zone:{fall:10,under:12,label:"Response"}},kicker:"Summary",site:"sin",title:"Carvedilol lowers the HVPG further from any starting point",line:"The dashed diagonal is no change. From {hvpg}, carvedilol lowers her HVPG to {hvpg@carv} and propranolol to {hvpg@prop}, both within the response zone.",notes:"Each point is this patient with more or less fibrosis, the HVPG read before a drug (across) and on it (up). The dashed diagonal is no change. The green zone is a response: a fall of 10% or more from baseline, or to 12 mmHg or less, which Baveno VIII carries from Baveno V and VI. Carvedilol lies below propranolol all the way along, because it also lowers the sinusoidal tone. In the model every patient responds to some degree; in practice about half do not respond to propranolol, which is why the HVPG fall, not the heart rate, is the measure. One model patient per point: real responses vary far more. (Baveno VIII Table 3; AASLD 2024 statement 12, carvedilol at CSPH.)",ask:["Her HVPG falls from 16.5 to 15.5 mmHg on propranolol. Has she responded?","No. That is a 6% fall and still >12 mmHg; a response needs a fall of \u226510% or a gradient \u226412 mmHg."]},{id:"summary",visual:"table",cols:["hvpg","ppg","map","liver"],asc:!1,vs:"first",rowHead:"Treatment",note:"How it works",of:[{id:"target",kicker:"Baseline",title:"Decompensated cirrhosis",note:"HVPG 16.5 mmHg, large varices, ascites"},{id:"prop",title:"Propranolol",note:"Lower inflow"},{id:"carv",title:"Carvedilol",note:"Lower inflow and resistance"},{id:"oct",kicker:"Vasoactive drug",title:"Octreotide",note:"Lower inflow, in variceal bleeding"},{id:"terli",kicker:"Vasoactive drug",title:"Terlipressin",note:"Lower inflow; bleeding and HRS-AKI"},{id:"vs",kicker:"Shunt",title:"TIPS",note:"Bypasses the liver"}],kicker:"Summary",title:"Effect of each treatment on the gradient",line:"Each treatment given alone to the same patient: drugs lower the gradient modestly, TIPS bypasses the resistance. Where the resistance is presinusoidal, carvedilol adds little.",notes:"Drugs reduce portal inflow (propranolol, octreotide, terlipressin) or intrahepatic resistance as well (carvedilol). Reduce or stop an NSBB when systolic BP stays <90 mmHg, MAP <65 mmHg, or AKI develops. EVL eradicates varices but leaves portal pressure high. TIPS lowers the gradient most and resolves ascites, at the cost of hepatic portal perfusion and a risk of hepatic encephalopathy. In practice they are combined: an NSBB with EVL after a bleed; octreotide or terlipressin, EVL and, for high-risk patients, preemptive TIPS in acute variceal bleeding. In schistosomiasis the HVPG misleads, because the WHVP reflects the sinusoids, which the periportal fibrosis spares. The table has no varix column: a beta-blocker does not shrink varices within days, but in the model the varix follows the pressure at once. The MAP column shows the pressure to watch on a beta-blocker.",ask:["Which treatment lowers the portal pressure gradient most, and what does it cost?","TIPS, at the cost of lower hepatic portal perfusion and a risk of hepatic encephalopathy."]}]};export{s as a};
